import type { DatabaseSync } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A job as returned by the HTTP API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A row of the `jobs` table, as selected with `SELECT *`. */
export interface JobRow {
  seq: number;
  id: string;
  idempotency_key: string | null;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  status: JobStatus;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getRow(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

export function getRowByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as JobRow | undefined;
}

export function listRows(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

/** Validates a parsed request body. Returns the payload with defaults applied, or the offending fields. */
export function validateNewJob(body: unknown): { ok: true; value: NewJob } | { ok: false; fields: FieldError[] } {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'Body must be a JSON object.' }] };
  }
  const fields: FieldError[] = [];
  const record = body as Record<string, unknown>;
  for (const key of Object.keys(record)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input } = record;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'Required.' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string.' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }

  const steps = intField(record, 'steps', 5, 1, 20, fields);
  const failAttempts = intField(record, 'failAttempts', 0, 0, 5, fields);

  if (fields.length > 0 || typeof input !== 'string') return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

function intField(
  record: Record<string, unknown>,
  name: string,
  def: number,
  min: number,
  max: number,
  fields: FieldError[],
): number {
  const value = record[name];
  if (value === undefined) return def;
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field: name, message: 'Must be an integer.' });
  } else if (value < min || value > max) {
    fields.push({ field: name, message: `Must be between ${min} and ${max}.` });
  }
  return value as number;
}

