import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase } from './db.ts';
import {
  getRow,
  getRowByKey,
  listRows,
  toJob,
  validateNewJob,
  type FieldError,
  type JobRow,
  type NewJob,
} from './jobs.ts';

/** A worker is "up" if it has written its heartbeat within this many milliseconds. */
const WORKER_STALE_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

class HttpError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
    readonly fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.code === 'invalid_request') error.fields = err.fields ?? [];
  send(res, err.status, { error });
}

function isJsonContentType(header: string | undefined): boolean {
  if (header === undefined) return false;
  return header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new HttpError(400, 'invalid_request', 'Request body is too large.', [{ field: 'body', message: 'Too large.' }]));
        req.resume();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const rawKey = req.headers['idempotency-key'];
  let key: string | undefined;
  if (rawKey !== undefined) {
    if (typeof rawKey === 'string' && IDEMPOTENCY_KEY_RE.test(rawKey)) key = rawKey;
    else fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  const text = await readBody(req);

  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  }

  let parsed: unknown;
  let parseOk = true;
  try {
    parsed = JSON.parse(text);
  } catch {
    parseOk = false;
    fields.push({ field: 'body', message: 'Body is not valid JSON.' });
  }

  let payload: NewJob | undefined;
  if (parseOk) {
    const result = validateNewJob(parsed);
    if (result.ok) payload = result.value;
    else fields.push(...result.fields);
  }

  if (fields.length > 0 || payload === undefined) {
    throw new HttpError(400, 'invalid_request', 'The request is invalid.', fields);
  }

  const outcome = createJob(db, payload, key);
  if (outcome.kind === 'conflict') {
    throw new HttpError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'replay' ? 200 : 201, toJob(outcome.row));
}

/** Creates a job, or finds the existing one for the idempotency key. Atomic with respect to the database. */
function createJob(
  database: DatabaseSync,
  payload: NewJob,
  key: string | undefined,
): { kind: 'created' | 'replay'; row: JobRow } | { kind: 'conflict' } {
  database.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = getRowByKey(database, key);
      if (existing) {
        database.exec('COMMIT');
        const same =
          existing.input === payload.input &&
          existing.steps === payload.steps &&
          existing.fail_attempts === payload.failAttempts;
        return same ? { kind: 'replay', row: existing } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    database
      .prepare(
        `INSERT INTO jobs (id, idempotency_key, input, steps, fail_attempts, attempts, status,
           progress_completed, available_at, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, 0, 'queued', 0, 0, ?, ?)`,
      )
      .run(id, key ?? null, payload.input, payload.steps, payload.failAttempts, now, now);
    const row = getRow(database, id)!;
    database.exec('COMMIT');
    return { kind: 'created', row };
  } catch (err) {
    database.exec('ROLLBACK');
    throw err;
  }
}

function workerIsUp(database: DatabaseSync): boolean {
  const row = database.prepare("SELECT ts FROM heartbeats WHERE name = 'worker'").get() as { ts: number } | undefined;
  return row !== undefined && Date.now() - Number(row.ts) <= WORKER_STALE_MS;
}

function route(req: IncomingMessage, res: ServerResponse): void {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') throw new HttpError(405, 'method_not_allowed', 'Method not allowed.');
    return send(res, 200, { status: 'ok', worker: workerIsUp(db) ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET') throw new HttpError(405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listRows(db).map(toJob) });
    if (method === 'POST') return void handleCreate(req, res).catch((err: unknown) => fail(res, err));
    throw new HttpError(405, 'method_not_allowed', 'Method not allowed.');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') throw new HttpError(405, 'method_not_allowed', 'Method not allowed.');
    const row = getRow(db, decodeURIComponent(match[1]!));
    if (!row) throw new HttpError(404, 'not_found', 'No such job.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'No such route.');
}

function fail(res: ServerResponse, err: unknown): void {
  if (res.headersSent) {
    res.end();
    return;
  }
  if (err instanceof HttpError) sendError(res, err);
  else {
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  }
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  try {
    const result = route(req, res);
    void result;
  } catch (err) {
    fail(res, err);
  }
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => {
    server.closeAllConnections();
  }, 1_000).unref();
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

