import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { MAX_ATTEMPTS, TRANSIENT_ERROR, type JobRow } from './jobs.ts';

/** Time for one processing step. */
const STEP_MS = 100;
/** How often an idle worker looks for queued work. */
const POLL_MS = 200;
/** How often the worker writes its heartbeat. The server reports "up" for 3 s after the last one. */
const HEARTBEAT_MS = 1_000;
/** Delay before a failed attempt is retried. Must be between 250 ms and 2 s. */
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const now = (): string => new Date().toISOString();

const selectNext = db.prepare(
  "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1",
);
const setRunning = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE id = ?",
);
const setProgress = db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?');
const setQueued = db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ? WHERE id = ?",
);
const setCompleted = db.prepare(
  "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?",
);
const setFailed = db.prepare(
  "UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, updated_at = ? WHERE id = ?",
);
const beat = db.prepare(
  "INSERT INTO heartbeats (name, ts) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET ts = excluded.ts",
);
const clearHeartbeat = db.prepare("DELETE FROM heartbeats WHERE name = 'worker'");

/**
 * Jobs left in `running` by a worker that died (or was stopped mid-attempt) go back to the queue.
 * They are processed again as a new attempt.
 */
function recoverInterrupted(): void {
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'").run(now());
}

/** Runs one attempt of a job. The attempt number is `attempts + 1`. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts + 1;
  setRunning.run(attempt, now(), job.id);

  // Attempt n fails at its first step, before any progress, while n <= failAttempts.
  if (attempt <= job.fail_attempts) {
    if (attempt >= MAX_ATTEMPTS) {
      setFailed.run(TRANSIENT_ERROR, now(), job.id);
    } else {
      setQueued.run(Date.now() + RETRY_DELAY_MS, now(), job.id);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Shutting down mid-attempt: put the job back so the next worker start processes it again.
      setQueued.run(0, now(), job.id);
      return;
    }
    setProgress.run(step, now(), job.id);
  }

  setCompleted.run(job.input.toUpperCase(), now(), job.id);
}

recoverInterrupted();
beat.run(Date.now());
const heartbeatTimer = setInterval(() => beat.run(Date.now()), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = selectNext.get(Date.now()) as JobRow | undefined;
    if (job) await runAttempt(job);
    else await sleep(POLL_MS);
  } catch (err) {
    console.error('worker error:', err);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
clearHeartbeat.run();
db.close();
console.log('worker stopped');

